#!/usr/bin/env sh

VERSION_FILE=$1

nil_or_string() {
    test -z "$1" && echo nil || echo "\"$1\""
}

{
    IFS= read -r commit_hash
    IFS= read -r change_id
    IFS= read -r dirty
    IFS= read -r commit_time
    IFS= read -r date_tag
} < "$VERSION_FILE"

echo "// swiftlint:disable all
// Generated by ReleaseVersionPlugin

import Foundation

public struct ReleaseVersion {
    public static let commit: String = \"$commit_hash\"
    public static let commitDate: Date = Date(timeIntervalSince1970: $commit_time)
    public static let isDirty: Bool = $(test -z "$dirty" && echo false || echo true)

    public static let tag: String? = $(nil_or_string "$date_tag")
    public static let changeID: String? = $(nil_or_string "$change_id")

    public static var shortCommit: String { return String(commit.prefix(7)) }
    public static var shortChangeID: String? { return changeID.map { String(\$0.prefix(8)) } }
}"
